/**
 * Typed license key fixtures for the reader/classifier/grants unit tests.
 *
 * These keys are generated by the AUTHORITATIVE license-key package generator
 * (a different codebase from the reader under test), so they prove
 * cross-implementation format compatibility: if the reader and a hand-rolled
 * builder shared the same misunderstanding of the format, only fixtures from
 * the real generator would catch it. For adversarial and edge cases, forge keys
 * with the in-test builder (`./buildTestKey`) instead.
 *
 * The holder is the obviously-fake "Test Fixture" on purpose. A [FREE] key never
 * expires, so a committed real one would be a directly usable free key - the
 * test holder makes its origin unambiguous.
 *
 * All expiry-carrying keys use exp 2026-08-27 (UTC midnight = 1787788800000).
 * Pin `Date.now` in tests; never rely on the real clock.
 */

/* eslint-disable max-len */

/**
 * The UTC-midnight epoch of the fixtures' shared expiry date (2026-08-27).
 *
 * @type {number}
 */
export const FIXTURE_EXPIRY_TIMESTAMP = Date.UTC(2026, 7, 27);

